UPDATE mobiles device SET operator_id = owner.operator_id
FROM users owner
WHERE device.operator_id IS NULL AND device.user_id = owner.user_id;

UPDATE scanners device SET operator_id = owner.operator_id
FROM users owner
WHERE device.operator_id IS NULL AND device.user_id = owner.user_id;

UPDATE terminals device SET operator_id = owner.operator_id
FROM users owner
WHERE device.operator_id IS NULL AND device.user_id = owner.user_id;
